import{_ as t,o as s,c as o,ae as r}from"./chunks/framework.Co1PSFSm.js";const g=JSON.parse('{"title":"","description":"This chapter goes over some fundamental concepts of Fresh.\\n","frontmatter":{"description":"This chapter goes over some fundamental concepts of Fresh.\\n"},"headers":[],"relativePath":"en/concepts/index.md","filePath":"en/concepts/index.md"}'),a={name:"en/concepts/index.md"};function n(i,e,c,l,d,h){return s(),o("div",null,[...e[0]||(e[0]=[r('<p>The way Fresh works is that it receives a <a href="https://developer.mozilla.org/en-US/docs/Web/API/Request" target="_blank" rel="noreferrer"><code>Request</code></a>, passes it through one or more middlewares until one of them responds. This can be an HTML response, a JSON response or any other response for that matter.</p><p>If the response was HTML and contained Islands (=interactive Preact components), Fresh will boot them up in the browser and execute the relevant JavaScript.</p><p>Here is an overview of the basic concepts in Fresh:</p><ul><li><a href="/docs/concepts/architecture.html"><strong>Architecture</strong></a> - How requests flow through Fresh, from middleware to islands</li><li><a href="/docs/concepts/app.html"><strong>App</strong></a> - Holds all the information about your app, like routes, etc</li><li><a href="/docs/concepts/middleware.html"><strong>Middleware</strong></a> - Respond to a request and return a <code>Response</code>. Used to set headers, or pass state to other middlewares. When a middleware doesn&#39;t call the next one and returns a response, it&#39;s usually called a &quot;handler&quot;.</li><li><a href="/docs/concepts/context.html"><strong>Context</strong></a> - Passed through every middleware. Use this to share state, trigger redirects or render HTML.</li><li><a href="/docs/concepts/routing.html"><strong>Routing</strong></a> - Responds to a particular URL and runs as chain of middlewares if it matches</li><li><a href="/docs/concepts/data-fetching.html"><strong>Data Fetching</strong></a> - Load data on the server and pass it to page components</li><li><a href="/docs/concepts/islands.html"><strong>Islands</strong></a> - Render interactive Preact components on the client</li><li><a href="/docs/concepts/signals.html"><strong>Signals</strong></a> - Reactive state management for islands</li><li><a href="/docs/concepts/static-files.html"><strong>Static Files</strong></a> - Serve images, CSS, and other assets</li><li><a href="/docs/concepts/file-routing.html"><strong>File Routing</strong></a> - Convention-based routing from the filesystem</li></ul><p>Advanced concepts:</p><ul><li><a href="/docs/advanced/app-wrapper.html"><strong>App wrapper</strong></a> - Responsible for the outer HTML structure, usually up to the <code>&lt;body&gt;</code>-tag</li><li><a href="/docs/advanced/layouts.html"><strong>Layouts</strong></a> - Re-use a shared layout when calling <code>ctx.render()</code> across routes</li><li><a href="/docs/advanced/partials.html"><strong>Partials</strong></a> - Stream in server generated content on the current page</li></ul>',6)])])}const u=t(a,[["render",n]]);export{g as __pageData,u as default};
